  if v_state is null then raise exception 'answer-length recut, wellcost refused: no row for intermediate module m06-the-professional-reading ord 15'; end if;
  if v_state = 'other' then raise exception 'answer-length recut, wellcost refused: intermediate module m06-the-professional-reading ord 15 matches neither its published nor its recut form'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions set options = '["Predict the final well cost to within the provision carried, since the provision bounds the whole error.", "Build one from a schedule and defend where each line came from and what its provision covers.", "Rank any two wells against each other on cost per metre and say which of the two was drilled the more efficiently.", "Say which percentile of the outcome the approved total reaches, reading it off the provision fraction."]'::jsonb
     where app_slug = 'wellcost' and tier = 'intermediate' and scope = 'module' and module_key is not distinct from 'm06-the-professional-reading' and ord = 15;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'answer-length recut, wellcost refused: intermediate module m06-the-professional-reading ord 15 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  select count(*) into v_total from public.academy_quiz_questions where app_slug = 'wellcost';
  if v_total <> 396 then raise exception 'answer-length recut, wellcost refused: the course holds % questions, expected 396', v_total; end if;
  raise notice 'answer-length recut, wellcost: % of 183 rows updated, the rest already carried the recut text', v_updated;
end $$;
